using System;
using System.Collections.Generic;
using System.Linq;
using Xunit.Abstractions;

namespace SharpCompute.Tests.Conformance;

/// <summary>
/// The conformance suite: every operator, conversion and intrinsic family of the shader language,
/// generated by <c>tools/gen_conformance.py</c>, run on the GPU and with <c>ForCpu</c> over the same
/// edge values (<see cref="ConformanceValues"/>) and compared slot by slot with each slot's policy.
/// This is the acceptance test for a change to the generator, the runtime or the CPU
/// implementations, and for any other backend. Run it alone with
/// <c>dotnet test --filter Category=Conformance</c>.
/// </summary>
[Trait("Category", "Conformance")]
public class ConformanceTests(ITestOutputHelper output)
{
    public static IEnumerable<object[]> Families() => ConformanceFamilies.All.Select(static f => new object[] { f.Title });

    [MetalTheory]
    [MemberData(nameof(Families))]
    public void Family_GivesTheSameResultsOnTheGpuAsWithForCpu(string title)
    {
        IConformanceFamily family = ConformanceFamilies.All.Single(f => f.Title == title);
        ConformanceResult result = family.Run(GraphicsDevice.GetDefault());

        output.WriteLine($"{result.Title}: {result.Slots} slots x {result.Threads} threads, {result.Comparisons} comparisons, {result.Flushed} equal only after flushing subnormals");
        Assert.True(result.Passed, "\n" + result.Report);
    }

    /// <summary>The comparisons are not vacuous: a changed GPU value is caught in every compared slot of every family.</summary>
    [MetalTheory]
    [MemberData(nameof(Families))]
    public void Family_ReportsEverySlot_WhenTheGpuResultsAreMutated(string title)
    {
        IConformanceFamily family = ConformanceFamilies.All.Single(f => f.Title == title);
        ConformanceResult result = family.Run(GraphicsDevice.GetDefault(), mutate: true);

        Assert.True(result.ComparedSlots > 0);
        Assert.Equal(result.ComparedSlots, result.FailedSlots);
    }

    [Fact]
    public void Families_HaveUniqueTitles_AndEveryUnspecifiedSlotSaysWhy()
    {
        Assert.Equal(ConformanceFamilies.All.Length, ConformanceFamilies.All.Select(static f => f.Title).Distinct().Count());
        Assert.All(
            ConformanceFamilies.All.SelectMany(static f => f.Slots).Where(static s => s.Check == Check.Unspecified),
            static s => Assert.False(string.IsNullOrWhiteSpace(s.Reason), s.Name));
        Assert.All(
            ConformanceFamilies.All.SelectMany(static f => f.Slots).Where(static s => s.Check == Check.Ulp),
            static s => Assert.InRange(s.Ulps, 1, 4));
    }
}
